"""
You are given two positive 0-indexed integer arrays nums1 and nums2, both of length n.

The sum of squared difference of arrays nums1 and nums2 is defined as the sum of (nums1[i] - nums2[i])2 for each 0 <= i < n.

You are also given two positive integers k1 and k2. You can modify any of the elements of nums1 by +1 or -1 at most k1 times.
Similarly, you can modify any of the elements of nums2 by +1 or -1 at most k2 times.

Return the minimum sum of squared difference after modifying array nums1 at most k1 times and modifying array nums2 at most k2 times.

Note: You are allowed to modify the array elements to become negative integers.

EXAMPLE 1:
Input: nums1 = [1,2,3,4], nums2 = [2,10,20,19], k1 = 0, k2 = 0
Output: 579
Explanation: The elements in nums1 and nums2 cannot be modified because k1 = 0 and k2 = 0.
The sum of square difference will be: (1 - 2)2 + (2 - 10)2 + (3 - 20)2 + (4 - 19)2 = 579.

EXAMPLE 2:
Input: nums1 = [1,4,10,12], nums2 = [5,8,6,9], k1 = 1, k2 = 1
Output: 43
Explanation: One way to obtain the minimum sum of square difference is:
- Increase nums1[0] once.
- Increase nums2[2] once.
The minimum of the sum of square difference will be:
(2 - 5)2 + (4 - 8)2 + (10 - 7)2 + (12 - 9)2 = 43.
Note that, there are other ways to obtain the minimum of the sum of square difference, but there is no way to obtain a sum smaller than 43.

CONSTRAINTS:
- n == nums1.length == nums2.length
- 1 <= n <= 105
- 0 <= nums1[i], nums2[i] <= 105
- 0 <= k1, k2 <= 109
"""


class Solution:
    @staticmethod
    def minSumSquareDiff(nums1: list[int], nums2: list[int], k1: int, k2: int) -> int:
        def heapify(arr, n, i):
            """Sift arr[i] down so the subtree rooted at i is a max-heap.

            n is the size of the heap (elements arr[0:n]).
            """
            while True:
                largest = i
                left = 2 * i + 1
                right = 2 * i + 2

                if left < n and arr[left] > arr[largest]:
                    largest = left
                if right < n and arr[right] > arr[largest]:
                    largest = right

                if largest == i:
                    return

                arr[i], arr[largest] = arr[largest], arr[i]
                i = largest

        def heap_sort(arr):
            """Sort arr in descending order (largest to smallest), in place, and return it."""
            n = len(arr)

            # Build a min-heap: start from the last non-leaf node and sift down.
            for i in range(n // 2 - 1, -1, -1):
                heapify(arr, n, i)

            # Repeatedly move the min (root) to the end and shrink the heap,
            # so the smallest values collect at the back.
            for end in range(n - 1, 0, -1):
                arr[0], arr[end] = arr[end], arr[0]
                heapify(arr, end, i)

            return arr

        def reduce_max(arr, k):
            """Decrement the maximum of a sorted (ascending) array by 1, k times."""
            a = list(arr)
            n = len(a)
            if n == 0 or k <= 0:
                return a

            cur = a[-1]  # current maximum
            start = n - 1  # first index of the group equal to cur
            while start > 0 and a[start - 1] == cur:
                start -= 1
            rem = 0

            while k > 0:
                cnt = n - start
                if start > 0 and k >= cnt * (cur - a[start - 1]):
                    # Lower the whole group to the next smaller value.
                    k -= cnt * (cur - a[start - 1])
                    cur = a[start - 1]
                    while start > 0 and a[start - 1] == cur:
                        start -= 1
                else:
                    # Spread the remaining operations across the group.
                    cur -= k // cnt
                    rem = k % cnt
                    k = 0

            for i in range(start, n):
                a[i] = cur
            for i in range(start, start + rem):
                a[i] -= 1  # leftmost elements take the extra decrement
            return a

        min_sum = 0
        difference = list()
        for num1, num2 in zip(nums1, nums2):
            difference.append(abs(num1 - num2))

        k = k1 + k2

        if k >= sum(difference):
            difference = [0] * len(difference)  # enough operations to zero everything
        else:
            # difference.sort()
            difference = heap_sort(difference)
            difference = reduce_max(difference, k)

        for element in difference:
            min_sum += element ** 2

        return min_sum


